// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 firstBlockTime, uint256 secondBlockTime, uint256 firstBlockNum, uint256 secondBlockNum) public {
        vm.assume(firstBlockNum % 15 != 0);
        vm.assume(secondBlockNum % 15 != 0);
        vm.assume(firstBlockTime > 0 && firstBlockTime < secondBlockTime);
        vm.assume(secondBlockTime <= type(uint256).max - 2);

        vm.warp(firstBlockTime);
        vm.roll(firstBlockNum);
        (bool ok1, bytes memory reason) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        uint256 past1 = c.pastBlockTime();

        uint256 targetTime = past1;
        vm.assume(targetTime > firstBlockTime);
        vm.warp(targetTime);
        vm.roll(secondBlockNum);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2);
    }
}
